import random

def check_k_colorable(adj, n, k):
    """Check if graph is k-colorable using backtracking"""
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            if all(colors[u] != c for u in adj[v]):
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

def build_adj(edges, n):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    return adj

def greedy_coloring(adj, n):
    colors = [-1] * n
    for v in range(n):
        neighbor_colors = set(colors[u] for u in adj[v] if colors[u] != -1)
        c = 0
        while c in neighbor_colors:
            c += 1
        colors[v] = c
    return max(colors) + 1

def random_5regular(n, seed=42):
    random.seed(seed)
    stubs = []
    for v in range(n):
        stubs.extend([v] * 5)

    for attempt in range(10000):
        random.shuffle(stubs)
        edges = set()
        valid = True
        for i in range(0, len(stubs), 2):
            u, v = stubs[i], stubs[i+1]
            if u == v or (min(u,v), max(u,v)) in edges:
                valid = False
                break
            edges.add((min(u,v), max(u,v)))
        if valid:
            return list(edges)
    return None

n = 14
edges = random_5regular(n)
adj = build_adj(edges, n)

is_4col = check_k_colorable(adj, n, 4)
print(f"4-colorable: {is_4col}")
if is_4col:
